head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


/*
 * <pre>
 * 법인관리 적출에서 검색일자 설정시 사용.
 * gTyp = 'A' : 코스닥 시가총액 미달 적출조회
 *        'C' : ETF 괴리율 적출조회
 *        'D' : ETF 괴리율 예고
 *        'E' : ETF LP평가기준 적출조회
 *        'F' : 주가요건
 *        'G' : 주가요건우려예고
 *        'H' : 시가총액
 *        'I' : 시가총액우려예고
 * </pre>
 */
/**
 * @method
 * @name fn_get_search_taskdd
 * @description desc
 * @param {string} dtsObj desc
 * @param {string} gTyp desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_get_search_taskdd = function(dtsObj, gTyp) {
    var url = "/listingCommon.do?method=listGeneral" + "&outputMessageId=AADD_IN" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=krx.lds.ins.lstmgt.detection.select.taskdd" + "&{P}param01=" + gTyp;
    dtsObj.DataID = encodeURI(url);
    dtsObj.reset();
    return dtsObj.getCellData(1, "BASE_DT");
};
/**
 * @method
 * @name fn_get_trstatcd
 * @description desc
 * @param {string} dtsObj desc
 * @param {string} gDt desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_get_trstatcd = function(dtsObj, gDt) {
    var url = "/listingCommon.do?method=listGeneral" + "&outputMessageId=ADMDTEC_TR_STATE_OUT" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=krx.lds.ins.lstmgt.detection.select.mktinfo.tr.kosdaq.magam" + "&{P}param01=" + gDt;
    dtsObj.DataID = encodeURI(url);
    dtsObj.reset();
    return dtsObj.getCellData(1, "TR_STATE_CD");
};
